using AIPMS.Application.Common.Models;using AIPMS.Application.Features.Evaluations.Commands;using AIPMS.Application.Features.Evaluations.DTOs;using AIPMS.Application.Features.Evaluations.Queries;using MediatR;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace AIPMS.Api.Controllers;
[ApiController,Authorize,Route("api/v1")]public sealed class EvaluationsController(ISender s):ControllerBase{[HttpPost("projects/{projectId:long}/evaluations")]public async Task<ActionResult<EvaluationDetailDto>> Create(long projectId,CreateEvaluationPayload p,CancellationToken ct)=>Ok(await s.Send(new CreateEvaluationDraftCommand(projectId,p.EvaluationType),ct));[HttpGet("projects/{projectId:long}/evaluations")]public async Task<ActionResult<PagedResult<EvaluationDto>>> List(long projectId,[FromQuery]int pageNumber=1,[FromQuery]int pageSize=20,CancellationToken ct=default)=>Ok(await s.Send(new GetProjectEvaluationsQuery(projectId,pageNumber,pageSize),ct));[HttpGet("evaluations/{id:long}")]public async Task<ActionResult<EvaluationDetailDto>> Get(long id,CancellationToken ct)=>Ok(await s.Send(new GetEvaluationQuery(id),ct));[HttpPut("evaluations/{id:long}/criteria/{criterionId:long}/score")]public async Task<IActionResult> Score(long id,long criterionId,ScorePayload p,CancellationToken ct){await s.Send(new UpdateEvaluationScoreCommand(id,criterionId,p.Score,p.Comments),ct);return NoContent();}[HttpPut("evaluations/{id:long}/comment")]public async Task<IActionResult> Comment(long id,CommentPayload p,CancellationToken ct){await s.Send(new UpdateEvaluationCommentCommand(id,p.Comments),ct);return NoContent();}[HttpPost("evaluations/{id:long}/finalize")]public async Task<IActionResult> Finalize(long id,CancellationToken ct){await s.Send(new FinalizeEvaluationCommand(id),ct);return NoContent();}}
public sealed record CreateEvaluationPayload(string EvaluationType);public sealed record ScorePayload(decimal Score,string? Comments);public sealed record CommentPayload(string? Comments);
